"""Abstract syntax tree nodes shared by the parser and the engine.

The parser builds these nodes.  Every expression node also carries a ``text``
attribute containing the exact source text of the expression; it is excluded
from comparison because it is only used for naming output columns.
"""

from dataclasses import dataclass, field
from typing import Any, List, Optional


def _text_field():
    return field(default="", compare=False, repr=False)


@dataclass
class Star:
    """``*`` in a select list or as the argument of ``COUNT(*)``."""

    text: str = _text_field()


@dataclass
class Literal:
    value: Any
    text: str = _text_field()


@dataclass
class Column:
    name: str
    text: str = _text_field()


@dataclass
class Unary:
    # op is '-' or 'NOT'
    op: str
    operand: Any
    text: str = _text_field()


@dataclass
class Binary:
    # op is one of OR, AND, =, !=, <>, <, <=, >, >=, +, -, *, /, ||
    op: str
    left: Any
    right: Any
    text: str = _text_field()


@dataclass
class IsNull:
    operand: Any
    negated: bool = False
    text: str = _text_field()


@dataclass
class InList:
    operand: Any
    items: List[Any] = field(default_factory=list)
    negated: bool = False
    text: str = _text_field()


@dataclass
class Between:
    operand: Any
    low: Any = None
    high: Any = None
    negated: bool = False
    text: str = _text_field()


@dataclass
class Like:
    operand: Any
    pattern: Any = None
    negated: bool = False
    text: str = _text_field()


@dataclass
class Call:
    # ``name`` is lower-cased by the parser.  ``args`` may contain Star for
    # COUNT(*).
    name: str
    args: List[Any] = field(default_factory=list)
    text: str = _text_field()


@dataclass
class OrderItem:
    expr: Any
    desc: bool = False


@dataclass
class SelectItem:
    expr: Any
    alias: Optional[str] = None


@dataclass
class Select:
    columns: List[SelectItem]
    distinct: bool = False
    table: str = ""
    where: Optional[Any] = None
    group_by: List[Any] = field(default_factory=list)
    having: Optional[Any] = None
    order_by: List[OrderItem] = field(default_factory=list)
    limit: Optional[int] = None
    offset: Optional[int] = None


def value_key(value):
    """A hashable key giving SQL-flavoured value equality.

    Numbers compare numerically regardless of int/float, while booleans,
    strings and NULL are distinct from numbers.
    """
    if value is None:
        return ("null",)
    if isinstance(value, bool):
        return ("bool", value)
    if isinstance(value, (int, float)):
        return ("num", value)
    return ("str", value)


def expr_key(node):
    """A hashable structural key for an expression, ignoring source text.

    Column names are lower-cased because column lookup is case-insensitive.
    """
    if isinstance(node, Star):
        return ("star",)
    if isinstance(node, Literal):
        return ("lit", value_key(node.value))
    if isinstance(node, Column):
        return ("col", node.name.lower())
    if isinstance(node, Unary):
        return ("unary", node.op, expr_key(node.operand))
    if isinstance(node, Binary):
        return ("binary", node.op, expr_key(node.left), expr_key(node.right))
    if isinstance(node, IsNull):
        return ("isnull", bool(node.negated), expr_key(node.operand))
    if isinstance(node, InList):
        return (
            "in",
            bool(node.negated),
            expr_key(node.operand),
            tuple(expr_key(item) for item in node.items),
        )
    if isinstance(node, Between):
        return (
            "between",
            bool(node.negated),
            expr_key(node.operand),
            expr_key(node.low),
            expr_key(node.high),
        )
    if isinstance(node, Like):
        return (
            "like",
            bool(node.negated),
            expr_key(node.operand),
            expr_key(node.pattern),
        )
    if isinstance(node, Call):
        return ("call", node.name.lower(), tuple(expr_key(arg) for arg in node.args))
    raise TypeError("unknown expression node: %r" % (node,))

