"""Execution engine for minisql SELECT queries."""

from functools import cmp_to_key

from . import ast
from . import values
from .ast import expr_key, value_key
from .errors import QueryError
from .parser import parse
from .table import load_table

_AGGREGATES = frozenset(("count", "sum", "avg", "min", "max"))
_COMPARISONS = frozenset(("=", "!=", "<>", "<", "<=", ">", ">="))


class Result:
    """The result of a query: output column names and rows of tuples."""

    __slots__ = ("columns", "rows")

    def __init__(self, columns, rows):
        self.columns = list(columns)
        self.rows = list(rows)

    def __eq__(self, other):
        if not isinstance(other, Result):
            return NotImplemented
        return self.columns == other.columns and self.rows == other.rows

    __hash__ = None

    def __repr__(self):
        return "Result({!r}, {!r})".format(self.columns, self.rows)


class _Schema:
    """Case-insensitive view of a table's header names."""

    __slots__ = ("columns", "_lookup")

    def __init__(self, columns):
        self.columns = list(columns)
        self._lookup = {}
        for index, name in enumerate(self.columns):
            self._lookup.setdefault(name.lower(), index)

    def index(self, name):
        try:
            return self._lookup[name.lower()]
        except KeyError:
            raise QueryError("unknown column: %s" % (name,))

    def canonical(self, name):
        return self.columns[self.index(name)]


class _Context:
    """Evaluation context: either one input row or one group of rows."""

    __slots__ = ("schema", "row", "group", "group_keys")

    def __init__(self, schema, row=None, group=None, group_keys=frozenset()):
        self.schema = schema
        self.row = row
        self.group = group
        self.group_keys = group_keys


# ---------------------------------------------------------------------------
# Expression validation (done eagerly, before looking at any rows)


def _children(node):
    if isinstance(node, ast.Unary):
        yield node.operand
    elif isinstance(node, ast.Binary):
        yield node.left
        yield node.right
    elif isinstance(node, ast.IsNull):
        yield node.operand
    elif isinstance(node, ast.InList):
        yield node.operand
        for item in node.items:
            yield item
    elif isinstance(node, ast.Between):
        yield node.operand
        yield node.low
        yield node.high
    elif isinstance(node, ast.Like):
        yield node.operand
        yield node.pattern
    elif isinstance(node, ast.Call):
        for arg in node.args:
            yield arg


def _has_aggregate(node):
    if isinstance(node, ast.Call) and node.name in _AGGREGATES:
        return True
    for child in _children(node):
        if _has_aggregate(child):
            return True
    return False


def _validate_expr(node, schema, in_aggregate=False):
    """Check column references, star placement, functions, and nesting."""
    if isinstance(node, ast.Literal):
        return
    if isinstance(node, ast.Column):
        schema.index(node.name)
        return
    if isinstance(node, ast.Star):
        raise QueryError("'*' is only allowed in SELECT * or COUNT(*)")

    if isinstance(node, ast.Call):
        if node.name in _AGGREGATES:
            if in_aggregate:
                raise QueryError("aggregates cannot be nested")
            if (
                node.name == "count"
                and len(node.args) == 1
                and isinstance(node.args[0], ast.Star)
            ):
                return
            if len(node.args) != 1:
                raise QueryError(
                    "%s requires exactly one argument" % node.name.upper()
                )
            _validate_expr(node.args[0], schema, in_aggregate=True)
            return
        values.validate_scalar(node.name, len(node.args))
        for arg in node.args:
            _validate_expr(arg, schema, in_aggregate)
        return

    for child in _children(node):
        _validate_expr(child, schema, in_aggregate)


# ---------------------------------------------------------------------------
# Expression evaluation


def _eval(node, context):
    # A subtree equal to a GROUP BY expression is constant within the group;
    # evaluate it from the group's first row (the group is never empty when
    # GROUP BY is present).
    if context.group is not None and expr_key(node) in context.group_keys:
        if not context.group:
            raise QueryError("cannot evaluate a column in an empty group")
        row_context = _Context(context.schema, row=context.group[0])
        return _eval(node, row_context)

    if isinstance(node, ast.Literal):
        return node.value

    if isinstance(node, ast.Column):
        if context.group is not None:
            raise QueryError(
                "column %s must appear in GROUP BY or be used in an aggregate"
                % (node.name,)
            )
        if context.row is None:
            raise QueryError("internal error: no row to evaluate against")
        return context.row[context.schema.index(node.name)]

    if isinstance(node, ast.Star):
        raise QueryError("'*' is only allowed in SELECT * or COUNT(*)")

    if isinstance(node, ast.Unary):
        value = _eval(node.operand, context)
        if node.op == "NOT":
            return values.sql_not(_condition_value(value))
        if node.op == "-":
            if value is None:
                return None
            if not values.is_number(value):
                raise QueryError("unary - requires a number")
            return -value
        raise QueryError("unknown unary operator: %s" % (node.op,))

    if isinstance(node, ast.Binary):
        op = node.op
        if op == "AND":
            return values.sql_and(
                _condition_value(_eval(node.left, context)),
                _condition_value(_eval(node.right, context)),
            )
        if op == "OR":
            return values.sql_or(
                _condition_value(_eval(node.left, context)),
                _condition_value(_eval(node.right, context)),
            )
        if op in _COMPARISONS:
            ordering = values.compare(
                _eval(node.left, context), _eval(node.right, context)
            )
            if ordering is None:
                return None
            if op == "=":
                return ordering == 0
            if op in ("!=", "<>"):
                return ordering != 0
            if op == "<":
                return ordering < 0
            if op == "<=":
                return ordering <= 0
            if op == ">":
                return ordering > 0
            return ordering >= 0
        return values.binary_op(
            op, _eval(node.left, context), _eval(node.right, context)
        )

    if isinstance(node, ast.IsNull):
        result = _eval(node.operand, context) is None
        return not result if node.negated else result

    if isinstance(node, ast.InList):
        operand = _eval(node.operand, context)
        items = [_eval(item, context) for item in node.items]
        if operand is None:
            result = None
        else:
            result = False
            saw_null = False
            for item in items:
                ordering = values.compare(operand, item)
                if ordering is None:
                    saw_null = True
                elif ordering == 0:
                    result = True
                    break
            if result is False and saw_null:
                result = None
        return values.sql_not(result) if node.negated else result

    if isinstance(node, ast.Between):
        operand = _eval(node.operand, context)
        low = _eval(node.low, context)
        high = _eval(node.high, context)
        lower_ok = _comparison_result(values.compare(low, operand))
        upper_ok = _comparison_result(values.compare(operand, high))
        result = values.sql_and(lower_ok, upper_ok)
        return values.sql_not(result) if node.negated else result

    if isinstance(node, ast.Like):
        result = values.like(
            _eval(node.operand, context), _eval(node.pattern, context)
        )
        return values.sql_not(result) if node.negated else result

    if isinstance(node, ast.Call):
        if node.name in _AGGREGATES:
            return _eval_aggregate(node, context)
        args = [_eval(arg, context) for arg in node.args]
        return values.scalar_function(node.name, args)

    raise QueryError("unknown expression")


def _comparison_result(ordering):
    if ordering is None:
        return None
    return ordering <= 0


def _condition_value(value):
    if value is not None and not isinstance(value, bool):
        raise QueryError("condition must be a boolean, got %s" % _type_name(value))
    return value


def _condition(node, context):
    return _condition_value(_eval(node, context))


def _type_name(value):
    if value is None:
        return "NULL"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, int):
        return "integer"
    if isinstance(value, float):
        return "number"
    if isinstance(value, str):
        return "text"
    return type(value).__name__


def _eval_aggregate(node, context):
    if context.group is None:
        raise QueryError("aggregates are not allowed here")

    if (
        node.name == "count"
        and len(node.args) == 1
        and isinstance(node.args[0], ast.Star)
    ):
        return len(context.group)

    if len(node.args) != 1:
        raise QueryError("%s requires exactly one argument" % node.name.upper())

    argument = node.args[0]
    collected = []
    for row in context.group:
        collected.append(_eval(argument, _Context(context.schema, row=row)))
    return values.aggregate(node.name, collected)


# ---------------------------------------------------------------------------
# Query planning helpers


def _projection(select, schema):
    """Return (expression per output column, output column names)."""
    columns = select.columns
    if len(columns) == 1 and isinstance(columns[0].expr, ast.Star):
        return (
            [ast.Column(name) for name in schema.columns],
            list(schema.columns),
        )

    expressions = []
    names = []
    for item in columns:
        if isinstance(item.expr, ast.Star):
            raise QueryError("'*' must be the entire select list")
        expressions.append(item.expr)
        if item.alias is not None:
            names.append(item.alias)
        elif isinstance(item.expr, ast.Column):
            names.append(schema.canonical(item.expr.name))
        else:
            names.append(item.expr.text)
    return expressions, names


def _order_specs(order_items, columns, schema):
    """Resolve ORDER BY items to ('out', index, desc) or ('expr', expr, desc)."""
    output_index = {}
    for index, name in enumerate(columns):
        output_index.setdefault(name.lower(), index)

    specs = []
    for item in order_items:
        node = item.expr
        if (
            isinstance(node, ast.Column)
            and node.name.lower() in output_index
        ):
            specs.append(("out", output_index[node.name.lower()], item.desc))
        elif (
            isinstance(node, ast.Literal)
            and isinstance(node.value, int)
            and not isinstance(node.value, bool)
        ):
            ordinal = node.value
            if ordinal < 1 or ordinal > len(columns):
                raise QueryError(
                    "ORDER BY position %d is out of range" % (ordinal,)
                )
            specs.append(("out", ordinal - 1, item.desc))
        else:
            _validate_expr(node, schema)
            specs.append(("expr", node, item.desc))
    return specs


def _deduplicate(items):
    seen = set()
    output = []
    for row, payload in items:
        key = tuple(value_key(value) for value in row)
        if key not in seen:
            seen.add(key)
            output.append((row, payload))
    return output


def _sort(items, specs, schema, grouped, group_keys):
    decorated = []
    for row, payload in items:
        if grouped:
            context = _Context(schema, group=payload, group_keys=group_keys)
        else:
            context = _Context(schema, row=payload)
        keys = []
        for kind, value, _desc in specs:
            if kind == "out":
                keys.append(row[value])
            else:
                keys.append(_eval(value, context))
        decorated.append((keys, row))

    def compare_rows(left, right):
        for index, (_kind, _value, desc) in enumerate(specs):
            a = left[0][index]
            b = right[0][index]
            if a is None and b is None:
                continue
            if a is None:
                return 1 if desc else -1
            if b is None:
                return -1 if desc else 1
            ordering = values.compare(a, b)
            if ordering:
                return -ordering if desc else ordering
        return 0

    decorated.sort(key=cmp_to_key(compare_rows))
    return [row for _keys, row in decorated]


# ---------------------------------------------------------------------------
# Entry point


def run(sql, directory="."):
    """Run ``sql`` against the CSV files in ``directory``."""
    select = parse(sql)
    table = load_table(directory, select.table)
    return _execute(select, table)


def _execute(select, table):
    schema = _Schema(table.columns)
    expressions, columns = _projection(select, schema)

    for expression in expressions:
        _validate_expr(expression, schema)

    if select.where is not None:
        if _has_aggregate(select.where):
            raise QueryError("aggregates are not allowed in WHERE")
        _validate_expr(select.where, schema)

    for expression in select.group_by:
        if _has_aggregate(expression):
            raise QueryError("aggregates are not allowed in GROUP BY")
        _validate_expr(expression, schema)

    if select.having is not None:
        _validate_expr(select.having, schema)

    order_specs = _order_specs(select.order_by, columns, schema)

    grouped = (
        bool(select.group_by)
        or any(_has_aggregate(expression) for expression in expressions)
        or (
            select.having is not None
            and _has_aggregate(select.having)
        )
        or any(
            kind == "expr" and _has_aggregate(value)
            for kind, value, _desc in order_specs
        )
    )

    # WHERE runs before grouping, always against individual rows.
    if select.where is None:
        filtered = list(table.rows)
    else:
        filtered = []
        for row in table.rows:
            context = _Context(schema, row=row)
            if _condition(select.where, context) is True:
                filtered.append(row)

    group_keys = frozenset(expr_key(expression) for expression in select.group_by)

    items = []
    if grouped:
        if select.group_by:
            groups = []
            positions = {}
            for row in filtered:
                row_context = _Context(schema, row=row)
                key = tuple(
                    value_key(_eval(expression, row_context))
                    for expression in select.group_by
                )
                position = positions.get(key)
                if position is None:
                    position = len(groups)
                    positions[key] = position
                    groups.append([])
                groups[position].append(row)
        else:
            # No GROUP BY: all rows (possibly zero) form a single group.
            groups = [filtered]

        for group in groups:
            context = _Context(schema, group=group, group_keys=group_keys)
            if select.having is not None:
                if _condition(select.having, context) is not True:
                    continue
            row = tuple(_eval(expression, context) for expression in expressions)
            items.append((row, group))
    else:
        for row in filtered:
            context = _Context(schema, row=row)
            if select.having is not None:
                if _condition(select.having, context) is not True:
                    continue
            output = tuple(_eval(expression, context) for expression in expressions)
            items.append((output, row))

    if select.distinct:
        items = _deduplicate(items)

    if order_specs:
        rows = _sort(items, order_specs, schema, grouped, group_keys)
    else:
        rows = [row for row, _payload in items]

    offset = select.offset or 0
    if select.limit is not None:
        rows = rows[offset : offset + select.limit]
    elif offset:
        rows = rows[offset:]

    return Result(columns, rows)

