"""Regression tests for engine-level rules that must not depend on data."""

import os
import tempfile
import unittest

import minisql


class EngineRuleTests(unittest.TestCase):
    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.directory = self._tmp.name
        with open(
            os.path.join(self.directory, "t.csv"), "w", newline=""
        ) as stream:
            stream.write("id,grp,val\n")
            stream.write("1,a,10\n")
            stream.write("2,a,\n")
            stream.write("3,b,5\n")

    def tearDown(self):
        self._tmp.cleanup()

    def run_query(self, sql):
        return minisql.run(sql, self.directory)

    def test_grouped_column_is_rejected_even_when_no_group_is_output(self):
        with self.assertRaises(minisql.QueryError):
            self.run_query("SELECT id FROM t HAVING COUNT(*) > 100")
        with self.assertRaises(minisql.QueryError):
            self.run_query("SELECT COUNT(*) FROM t HAVING COALESCE(TRUE, id)")
        with self.assertRaises(minisql.QueryError):
            self.run_query(
                "SELECT id, COUNT(*) FROM t WHERE FALSE GROUP BY grp"
            )
        with self.assertRaises(minisql.QueryError):
            self.run_query(
                "SELECT COUNT(*) FROM t HAVING COUNT(*) > 100 ORDER BY id"
            )

    def test_grouped_expression_may_use_grouped_columns(self):
        result = self.run_query(
            "SELECT grp, val * 2 FROM t GROUP BY grp, val ORDER BY val"
        )
        self.assertEqual(result.columns, ["grp", "val * 2"])
        self.assertEqual(
            result.rows, [("a", None), ("b", 10), ("a", 20)]
        )

    def test_aggregate_over_empty_input_still_valid(self):
        result = self.run_query("SELECT COUNT(*) FROM t WHERE FALSE")
        self.assertEqual(result.rows, [(0,)])
        result = self.run_query(
            "SELECT COUNT(*), SUM(val), AVG(val) FROM t WHERE FALSE"
        )
        self.assertEqual(result.rows, [(0, None, None)])

    def test_large_integer_division_returns_float(self):
        number = "1" + "0" * 400
        result = self.run_query(
            "SELECT ({0}) / ({0}), 1 / ({0}) FROM t".format(number)
        )
        self.assertEqual(result.rows[0], (1.0, 0.0))

    def test_deeply_nested_query_raises_query_error(self):
        sql = "SELECT " + "(" * 125 + "1" + ")" * 125 + " FROM t"
        with self.assertRaises(minisql.QueryError):
            self.run_query(sql)


if __name__ == "__main__":
    unittest.main()

